/* Boot logo component: RLE-compressed RGB565 decoder.
 * Data generated by tools/logo_convert.py -> build/gen/boot_logo.h
 *
 * RLE format: pairs of (count, rgb565_be). count=0 ends the row.
 * The logo is BOOT_LOGO_W wide, BOOT_LOGO_IMG_H tall content
 * centered in a BOOT_LOGO_H canvas (Y offset = BOOT_LOGO_Y_OFF). */

#include "boot_logo.h"

static uint16_t logo_row_buf[BOOT_LOGO_W];

static const uint8_t *logo_decode_row(const uint8_t *p)
{
    uint32_t x = 0;
    while (*p) {
        uint32_t run = *p++;
        uint16_t px = (uint16_t)(p[0] | ((uint16_t)p[1] << 8));
        p += 2;
        while (run-- && x < (uint32_t)BOOT_LOGO_W)
            logo_row_buf[x++] = px;
    }
    p++;
    while (x < (uint32_t)BOOT_LOGO_W)
        logo_row_buf[x++] = 0;
    return p;
}

static void logo_draw(uint32_t x, uint32_t y)
{
    const uint8_t *p = boot_logo_rle;
    uint32_t row;
    for (row = 0; row < (uint32_t)BOOT_LOGO_H; row++) {
        p = logo_decode_row(p);
        lcd_sync();
        lcd_blit(x, y + row, (uint32_t)BOOT_LOGO_W, 1, logo_row_buf);
    }
}

static void logo_draw_content(uint32_t x, uint32_t y)
{
    const uint8_t *p = boot_logo_rle;
    uint32_t row;
    for (row = 0; row < (uint32_t)BOOT_LOGO_Y_OFF; row++) {
        while (*p) { p += 3; }
        p++;
    }
    for (row = 0; row < (uint32_t)BOOT_LOGO_IMG_H; row++) {
        p = logo_decode_row(p);
        lcd_sync();
        lcd_blit(x, y + row, (uint32_t)BOOT_LOGO_W, 1, logo_row_buf);
    }
}
